SELECT [u].[FirstName] + N' ' + [u].[LastName] AS [CustomerName], [u].[Email], [t].[PlanName] FROM [SmartMeters] AS [s] INNER JOIN [Users] AS [u] ON [s].[UserId] = [u].[UserId] INNER JOIN [TariffPlans] AS [t] ON [s].[TariffPlanId] = [t].[TariffPlanId] WHERE [s].[IsActive] = CAST(1 AS bit) ORDER BY [u].[FirstName] + N' ' + [u].[LastName]
SELECT [e].[SmartMeterId] AS [MeterId], COALESCE(SUM([e].[UnitsKWh]), 0.0) AS [TotalEnergy], COALESCE(SUM([e].[PowerKW]), 0.0) AS [TotalPower] FROM [EnergyLogs] AS [e] WHERE DATEPART(year, [e].[Timestamp]) = 2026 AND DATEPART(month, [e].[Timestamp]) = 8 GROUP BY [e].[SmartMeterId] HAVING COALESCE(SUM([e].[UnitsKWh]), 0.0) > 10.0

SELECT COALESCE([u].[FirstName], N'') + N' ' + COALESCE([u].[LastName], N'') AS [FullName], [s].[MeterSerialNumber], [a].[AlertTitle], [s0].[SubstationName] FROM [Alerts] AS [a] INNER JOIN [SmartMeters] AS [s] ON [a].[SmartMeterId] = [s].[MeterId] LEFT JOIN [Users] AS [u] ON [s].[AssignedTechnicianId] = [u].[UserId] INNER JOIN [Transformers] AS [t] ON [s].[TransformerId] = [t].[TransformerId] INNER JOIN [Substations] AS [s0] ON [t].[SubstationId] = [s0].[SubstationId] WHERE [a].[Status] IN ('Critical', 'Pending')

SELECT [e].[SmartMeterId] AS [MeterId], MAX([e].[UnitsKWh]) AS [PeakHour] FROM [EnergyLogs] AS [e] WHERE [e].[IsPeakHour] = CAST(1 AS bit) GROUP BY [e].[SmartMeterId]

SELECT [u].[UserId], [u].[FirstName] + N' ' + [u].[LastName] AS [CustomerName], (   SELECT COALESCE(SUM([s1].[value]), 0.0)    FROM [SmartMeters] AS [s]    OUTER APPLY (        SELECT COALESCE(SUM([e].[UnitsKWh]), 0.0) AS [value]        FROM [EnergyLogs] AS [e]        WHERE [s].[MeterId] = [e].[SmartMeterId]    ) AS [s1]    WHERE [u].[UserId] = [s].[UserId]) AS [Total], (    SELECT COALESCE(SUM([s2].[value]), 0.0)    FROM [SmartMeters] AS [s0]    INNER JOIN [TariffPlans] AS [t] ON [s0].[TariffPlanId] = [t].[TariffPlanId]    OUTER APPLY (        SELECT COALESCE(SUM(CASE            WHEN [e0].[IsPeakHour] = CAST(1 AS bit) THEN [e0].[UnitsKWh] * [t].[PeakHourPricePerUnit]            ELSE [e0].[UnitsKWh] * [t].[PricePerUnit]        END), 0.0) AS [value]        FROM [EnergyLogs] AS [e0]        WHERE [s0].[MeterId] = [e0].[SmartMeterId]    ) AS [s2]    WHERE [u].[UserId] = [s0].[UserId]) AS [TotalCostFormatted]FROM [Users] AS [u]